import java.io.*;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;
    static InputStream in = System.in;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static long readLong() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        boolean negative = c == '-';
        if (c == '-' || c == '+') c = readByte();
        long x = 0;
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return negative ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) readLong();
        int turns = (int) (readLong() % 4); // four rotations restore the matrix
        int[] a = new int[n * n];
        for (int i = 0; i < a.length; i++) a[i] = (int) readLong();
        for (int step = 0; step < turns; step++) {
            // Each representative in the strict top triangle r < c < n-1-r starts one four-cycle.
            for (int r = 0; r < n / 2; r++) {
                for (int c = r + 1; c < n - 1 - r; c++) {
                    int p = r * n + c, q = c * n + n - 1 - r, u = (n - 1 - r) * n + n - 1 - c, v = (n - 1 - c) * n + r;
                    int saved = a[p];
                    a[p] = a[v];
                    a[v] = a[u];
                    a[u] = a[q];
                    a[q] = saved;
                }
            }
        }
        BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 16);
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < n; r++) {
            sb.setLength(0);
            for (int c = 0; c < n; c++) {
                sb.append(a[r * n + c]).append(c + 1 == n ? '\n' : ' ');
            }
            out.write(sb.toString().getBytes());
        }
        out.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() int64 {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		negative := c == '-'
		if c == '-' || c == '+' {
			c, err = reader.ReadByte()
		}
		var x int64
		for err == nil && c > ' ' {
			x = x*10 + int64(c-'0')
			c, err = reader.ReadByte()
		}
		if negative {
			return -x
		}
		return x
	}
	n := int(readInt())
	turns := int(readInt() % 4) // four rotations restore the matrix
	a := make([]int32, n*n)
	for i := range a {
		a[i] = int32(readInt())
	}
	for step := 0; step < turns; step++ {
		// Each representative in the strict top triangle r < c < n-1-r starts one four-cycle.
		for r := 0; r < n/2; r++ {
			for c := r + 1; c < n-1-r; c++ {
				p, q, u, v := r*n+c, c*n+n-1-r, (n-1-r)*n+n-1-c, (n-1-c)*n+r
				a[p], a[v], a[u], a[q] = a[v], a[u], a[q], a[p]
			}
		}
	}
	writer := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer writer.Flush()
	line := make([]byte, 0, 64)
	for r := 0; r < n; r++ {
		for c := 0; c < n; c++ {
			line = strconv.AppendInt(line[:0], int64(a[r*n+c]), 10)
			if c+1 == n {
				line = append(line, '\n')
			} else {
				line = append(line, ' ')
			}
			writer.Write(line)
		}
	}
}
